:root {
  --bg: #1e1e2f;
  --surface: #2a2a40;
  --primary: #6c5ce7;
  --accent: #fd79a8;
  --text: #f0f0f0;
  --card-back: #3d3d5c;
  --card-border: #5a5a7a;
  --radius: 8px;
  --gap: 10px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.game-container {
  background: var(--surface);
  padding: 24px 20px;
  border-radius: 16px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  max-width: 600px;
  width: 100%;
  text-align: center;
}

h1 {
  font-size: 1.6rem;
  margin-bottom: 16px;
  color: var(--accent);
  letter-spacing: 1px;
}

.status-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
  flex-wrap: wrap;
  gap: 8px;
}

#moves {
  font-size: 1.1rem;
  font-weight: 600;
}

.btn {
  background: var(--primary);
  color: white;
  border: none;
  padding: 10px 20px;
  border-radius: var(--radius);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  font-family: inherit;
}

.btn:hover {
  background: #7d6ff0;
}

.btn:active {
  transform: scale(0.96);
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--gap);
  margin-bottom: 16px;
}

.card {
  aspect-ratio: 1 / 1;
  background: var(--card-back);
  border: 3px solid var(--card-border);
  border-radius: var(--radius);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 700;
  color: transparent;
  transition: background 0.2s, border-color 0.2s, transform 0.1s;
  user-select: none;
  position: relative;
  overflow: hidden;
}

.card:hover {
  border-color: var(--accent);
  transform: scale(1.04);
}

.card:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.card.flipped {
  background: var(--flip-color, #fff);
  border-color: var(--flip-color, #fff);
  color: transparent;
}

.card.matched {
  background: var(--flip-color, #fff);
  border-color: var(--flip-color, #fff);
  cursor: default;
  opacity: 0.7;
  transform: none;
}

.card.matched:hover {
  transform: none;
}

.win-message {
  font-size: 1.3rem;
  font-weight: 700;
  color: var(--accent);
  min-height: 1.8em;
  margin-top: 8px;
}

@media (max-width: 480px) {
  .game-container {
    padding: 16px 12px;
  }
  h1 {
    font-size: 1.3rem;
  }
  .board {
    gap: 6px;
  }
  .card {
    border-width: 2px;
  }
}

(function () {
  'use strict';

  const COLORS = [
    '#e74c3c', '#3498db', '#2ecc71', '#f1c40f',
    '#9b59b6', '#e67e22', '#1abc9c', '#e84393'
  ];

  const board = document.getElementById('board');
  const movesEl = document.getElementById('moves');
  const winEl = document.getElementById('win-message');
  const newGameBtn = document.getElementById('new-game');

  let cards = [];
  let flipped = [];
  let matchedCount = 0;
  let moves = 0;
  let lock = false;

  function shuffle(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  }

  function createDeck() {
    const deck = [];
    COLORS.forEach((color, idx) => {
      deck.push({ id: idx, color });
      deck.push({ id: idx, color });
    });
    return shuffle(deck);
  }

  function renderBoard() {
    board.innerHTML = '';
    cards = createDeck();
    flipped = [];
    matchedCount = 0;
    moves = 0;
    lock = false;
    movesEl.textContent = 'Moves: 0';
    winEl.textContent = '';

    cards.forEach((card, index) => {
      const el = document.createElement('button');
      el.className = 'card';
      el.setAttribute('role', 'gridcell');
      el.setAttribute('aria-label', 'Hidden card');
      el.dataset.index = index;
      el.dataset.id = card.id;
      el.dataset.color = card.color;
      el.addEventListener('click', handleCardClick);
      board.appendChild(el);
    });
  }

  function handleCardClick(e) {
    const el = e.currentTarget;
    if (lock || el.classList.contains('flipped') || el.classList.contains('matched')) return;

    el.classList.add('flipped');
    el.style.setProperty('--flip-color', el.dataset.color);
    el.setAttribute('aria-label', 'Flipped card');
    flipped.push(el);

    if (flipped.length === 2) {
      moves++;
      movesEl.textContent = 'Moves: ' + moves;
      checkMatch();
    }
  }

  function checkMatch() {
    const [a, b] = flipped;
    lock = true;

    if (a.dataset.id === b.dataset.id) {
      a.classList.add('matched');
      b.classList.add('matched');
      a.setAttribute('aria-label', 'Matched card');
      b.setAttribute('aria-label', 'Matched card');
      matchedCount += 2;
      flipped = [];
      lock = false;
      if (matchedCount === cards.length) {
        winEl.textContent = 'You win! Moves: ' + moves;
      }
    } else {
      setTimeout(() => {
        a.classList.remove('flipped');
        b.classList.remove('flipped');
        a.style.removeProperty('--flip-color');
        b.style.removeProperty('--flip-color');
        a.setAttribute('aria-label', 'Hidden card');
        b.setAttribute('aria-label', 'Hidden card');
        flipped = [];
        lock = false;
      }, 800);
    }
  }

  newGameBtn.addEventListener('click', renderBoard);
  renderBoard();
})();
